package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import static org.junit.Assert.*;

/**
 * Unit tests for org.jsoup.nodes.Node#hasAttr(String)
 */
public class Node_hasAttr_TriageGen1Test {

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    /**
     * Since Node is an abstract class, we use an implementation 
     * (like Element, which is a concrete subclass of Node) to test the logic.
     * However, for pure Node tests, we can use Element or a mock.
     */

    @Test
    public void testHasAttr_WithNullKey_ThrowsException() {
        Element element = new Element("");
        thrown.expect(IllegalArgumentException.class);
        // Validate.notNull throws IllegalArgumentException if null
        element.hasAttr(null);
    }

    @Test
    public void testHasAttr_WithExistingAttribute_ReturnsTrue() {
        Element element = new Element("");
        String key = "href";
        element.attr(key, "https://example.com");

        assertTrue("Should return true when the attribute exists", element.hasAttr(key));
    }

    @Test
    public void testHasAttr_WithNonExistingAttribute_ReturnsFalse() {
        Element element = new Element("");
        String key = "nonexistent";

        assertFalse("Should return false when the attribute does not exist", element.hasAttr(key));
    }

    @Test
    public void testHasAttr_WithEmptyStringKey_ReturnsFalse() {
        Element element = new Element("");
        String key = "";

        assertFalse("Should return false for an empty string key if not set", element.hasAttr(key));
    }

    @Test
    public void testHasAttr_AfterRemovingAttribute_ReturnsFalse() {
        Element element = new Element("");
        String key = "class";
        element.attr(key, "container");

        assertTrue(element.hasAttr(key));

        element.removeAttr(key);

        assertFalse("Should return false after the attribute has been removed", element.hasAttr(key));
    }

    @Test
    public void testHasAttr_WithEmptyAttributeValue_ReturnsTrue() {
        Element element = new Element("");
        String key = "data-empty";
        element.attr(key, "");

        assertTrue("Should return true even if the attribute value is an empty string", element.hasAttr(key));
    }
}
